final_sql:
SELECT product_id, name, category, price, stock
FROM products
WHERE category = 'Electronics';

SELECT *
FROM customers
WHERE country = 'USA';

SELECT COUNT(*) AS order_count
FROM orders
WHERE strftime('%Y', order_date) = '2024';

SELECT product_id, name, category, price, stock
FROM products
WHERE price > 100;

SELECT category, COUNT(*) AS product_count
FROM products
GROUP BY category;

SELECT *
FROM customers
WHERE signup_date LIKE '2024%';

SELECT o.order_id, c.name AS customer_name, o.product_id, o.quantity, o.order_date, o.total_amount
FROM orders o
JOIN customers c ON o.customer_id = c.customer_id;

SELECT *
FROM orders
WHERE total_amount > (SELECT AVG(total_amount) FROM orders);

SELECT employee_id, name, dept_id, salary, hire_date
FROM employees
WHERE strftime('%Y', hire_date) = '2024';

SELECT SUM(amount + COALESCE(bonus, 0)) AS total_payroll
FROM payroll
WHERE month = '2024-01';

SELECT employee_id, name, dept_id, salary, hire_date, manager_id
FROM employees
WHERE salary > 100000;

SELECT e.employee_id, e.name, d.dept_name
FROM employees e
LEFT JOIN departments d ON e.dept_id = d.dept_id;

SELECT employee_id, name, dept_id, salary, hire_date
FROM employees
WHERE manager_id IS NULL;

SELECT SUM(bonus) AS total_bonuses
FROM payroll
WHERE month = '2024-01';

SELECT employee_id, name, dept_id, salary, hire_date, manager_id
FROM employees
WHERE hire_date < '2023-01-01';

SELECT product_id, name, category, price, stock
FROM products
WHERE stock BETWEEN 50 AND 150;

SELECT customer_id, name, email, country, signup_date
FROM customers
WHERE name LIKE 'A%';

SELECT product_id, name, category, price, stock
FROM products
ORDER BY price DESC;

SELECT o.order_id, p.name AS product_name, o.quantity
FROM orders o
JOIN products p ON o.product_id = p.product_id;

SELECT product_id, name, category, price, stock
FROM products
WHERE stock > 100;

SELECT category, COUNT(*) AS total_products
FROM products
GROUP BY category;

SELECT employee_id, name, dept_id, salary, hire_date
FROM employees
WHERE strftime('%Y', hire_date) = '2021';

SELECT employee_id, name, dept_id, salary
FROM employees
WHERE salary BETWEEN 80000 AND 120000;

SELECT p.payroll_id, p.month, p.amount, p.bonus, e.name AS employee_name
FROM payroll p
JOIN employees e ON p.employee_id = e.employee_id;

SELECT COUNT(*) AS employee_count
FROM employees
WHERE manager_id = 1;

SELECT AVG(bonus)
FROM payroll
WHERE month = '2024-01';

SELECT employee_id, name, dept_id, salary, hire_date, manager_id
FROM employees
WHERE name LIKE '%Dev%';

SELECT title, author, total_copies, available_copies
FROM books
WHERE available_copies = 0;

SELECT *
FROM books
WHERE genre = 'Technology';

SELECT name, email, join_date, membership_type
FROM members
WHERE membership_type = 'Premium';

SELECT COUNT(*) AS returned_loans
FROM loans
WHERE return_date IS NOT NULL;

SELECT l.loan_id, m.name, l.book_id, l.loan_date, l.due_date, l.return_date
FROM loans l
JOIN members m ON l.member_id = m.member_id;
